package com.jr12866.dartcoach.core

import com.google.gson.JsonObject
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNotNull
import kotlin.test.assertNull
import kotlin.test.assertTrue

/**
 * The Kotlin core must agree with the Python one, case for case.
 *
 * These tests read the corpus generated by
 * `tools/parity/parity_gen.py` in the Windows repo. Every case says what the
 * Python produced for a given input, and this file asserts the Kotlin
 * produces the same.
 *
 * This is the whole point of porting rather than rewriting. The Python
 * implementation was tuned through a lot of live failures, and the rules it
 * ended up with - "one eighteen" is 19, a destructive command needs the wake
 * word, the answer predicates are separate from the parser - are not
 * obvious from reading the code. They are pinned here instead.
 *
 * The corpus is generated from the Python side and checked in. If the Python
 * behaviour changes deliberately, regenerate the corpus and read the diff.
 */
class ParityTest {

    // ----------------------------------------------------------------------
    // parser.json
    // ----------------------------------------------------------------------

    @Test
    fun `parses every phrase the same way the Python parser does`() {
        val cases = Corpus.cases("parser.json")
        assertCorpusSize(cases.size, 100, "parser")

        var checked = 0
        for (case in cases) {
            val id = case.str("id")!!
            val expect = case.get("expect").asJsonObject
            val command = expect.str("command")

            // The confirmation predicates are not the parser. They are pinned
            // separately, below, because the coach calls them directly.
            if (command == "__is_confirmation__") {
                continue
            }

            val text = case.str("text")!!
            val state = GameState(
                remainingScore = case.get("state").asJsonObject.int("remaining_score")!!,
                turnsPlayed = case.get("state").asJsonObject.int("turns_played")!!,
            )

            val result = Parser.parse(text, state)

            assertEquals(
                command,
                result.command,
                "command differs for '$id' (text: '$text')",
            )
            assertSameNullable(
                expect.int("score"),
                result.score,
                "score differs for '$id' (text: '$text')",
            )
            assertSameIntList(
                expect.intList("darts"),
                result.darts,
                "darts differ for '$id' (text: '$text')",
            )
            assertSameNullable(
                expect.int("double"),
                result.double,
                "double differs for '$id' (text: '$text')",
            )
            assertSameNullable(
                expect.bool("refused"),
                result.refused,
                "refused differs for '$id' (text: '$text')",
            )
            assertSameNullable(
                expect.bool("needs_confirmation"),
                result.needsConfirmation,
                "needs_confirmation differs for '$id' (text: '$text')",
            )
            checked++
        }

        // The corpus holds the parse cases and the confirmation cases. Only
        // the parse cases are counted here; the confirmation ones are
        // checked by the test below.
        assertCorpusSize(checked, 70, "parser (parse cases)")
    }

    @Test
    fun `answers the same way the Python answer predicates do`() {
        val cases = Corpus.cases("parser.json")
        var checked = 0

        for (case in cases) {
            val id = case.str("id")!!
            if (!id.startsWith("confirm-")) {
                continue
            }
            val expect = case.get("expect").asJsonObject
            val text = case.str("text")!!

            assertSameNullable(
                expect.bool("score"),
                Parser.isConfirmation(text),
                "is_confirmation differs for '$id' (text: '$text')",
            )
            assertSameNullable(
                expect.bool("darts"),
                Parser.isCancellation(text),
                "is_cancellation differs for '$id' (text: '$text')",
            )
            checked++
        }

        assertCorpusSize(checked, 60, "parser (answer cases)")
    }

    // ----------------------------------------------------------------------
    // planner.json
    // ----------------------------------------------------------------------

    @Test
    fun `plans every score the same way the Python planner does`() {
        val cases = Corpus.cases("plans.json")
        assertCorpusSize(cases.size, 501, "plans")

        val planner = Planner.shared
        var plans = 0

        for (case in cases) {
            val id = case.str("id")!!
            val remaining = case.int("remaining")!!
            val expect = case.get("expect")

            val plan = planner.planFor(remaining)
            assertPlanMatches(id, expect.asJsonObject, plan)
            plans++
        }

        assertTrue(plans >= 501, "Only $plans plans were checked")
    }

    @Test
    fun `routes onto a chosen double the same way the Python planner does`() {
        val cases = Corpus.cases("routes.json")
        assertCorpusSize(cases.size, 6000, "routes")

        val planner = Planner.shared
        var routes = 0

        for (case in cases) {
            val id = case.str("id")!!
            val remaining = case.int("remaining")!!
            val preferred = case.int("preferred_double")!!
            val expect = case.get("expect")

            val route = planner.routeToDouble(remaining, preferred)
            if (expect.isJsonNull) {
                // The Python planner found no shot at that double. The Kotlin
                // one must not invent one.
                assertNull(route, "route should be absent for '$id'")
            } else {
                assertNotNull(route, "route missing for '$id'")
                assertRouteMatches(id, expect.asJsonObject, route!!)
            }
            routes++
        }

        assertTrue(routes > 6000, "Only $routes routes were checked")
    }

    private fun assertPlanMatches(
        id: String,
        expect: JsonObject,
        plan: Plan,
    ) {
        assertEquals(expect.strList("labels"), plan.labels, "labels differ for '$id'")
        assertEquals(expect.int("leaves"), plan.leaves, "leaves differ for '$id'")
        assertEquals(expect.bool("finishes"), plan.finishes, "finishes differ for '$id'")
        assertSameStringList(
            expect.strList("fallback_labels"),
            plan.fallbackLabels,
            "fallback_labels differ for '$id'",
        )
        assertSameNullable(
            expect.int("fallback_leaves"),
            plan.fallbackLeaves,
            "fallback_leaves differ for '$id'",
        )
        assertEquals(expect.strList("doubles"), plan.doubles, "doubles differ for '$id'")
        assertEquals(expect.str("speak"), plan.speak(), "speak differs for '$id'")
        assertSameStringList(
            expect.strList("display_lines"),
            plan.displayLines,
            "display_lines differ for '$id'",
        )
    }

    private fun assertRouteMatches(
        id: String,
        expect: JsonObject,
        route: Route,
    ) {
        assertEquals(expect.strList("labels"), route.labels, "labels differ for '$id'")
        assertEquals(expect.int("leaves"), route.leaves, "leaves differ for '$id'")
        assertEquals(expect.bool("finishes"), route.finishes, "finishes differ for '$id'")
        assertSameStringList(
            expect.strList("fallback_labels"),
            route.fallbackLabels,
            "fallback_labels differ for '$id'",
        )
        assertSameNullable(
            expect.int("fallback_leaves"),
            route.fallbackLeaves,
            "fallback_leaves differ for '$id'",
        )
        assertEquals(expect.str("speak"), route.speak(), "speak differs for '$id'")
        assertSameStringList(
            expect.strList("display_lines"),
            route.displayLines,
            "display_lines differ for '$id'",
        )
        assertEquals(expect.int("double"), route.double, "double differs for '$id'")
    }

    // ----------------------------------------------------------------------
    // state.json
    // ----------------------------------------------------------------------

    @Test
    fun `tracks a leg the same way the Python state machine does`() {
        val cases = Corpus.cases("state.json")

        for (case in cases) {
            val id = case.str("id")!!
            val expect = case.get("expect").asJsonObject
            val state = GameState()

            val preferred = case.int("preferred_double")
            if (preferred != null) {
                state.preferredDouble = preferred
            }

            val turns = case.get("turns").asJsonArray
            for (i in 0 until turns.size()) {
                state.recordTurn(turns.get(i).asInt)
            }

            assertSameNullable(
                expect.int("remaining_score"),
                state.remainingScore,
                "remaining_score differs for '$id'",
            )
            assertSameNullable(
                expect.int("turns_played"),
                state.turnsPlayed,
                "turns_played differs for '$id'",
            )
            assertSameIntList(
                expect.intList("current_darts"),
                state.currentDarts,
                "current_darts differ for '$id'",
            )
            assertSameNullable(
                expect.int("preferred_double"),
                state.preferredDouble,
                "preferred_double differs for '$id'",
            )
        }
    }

    // ----------------------------------------------------------------------
    // helpers.json
    // ----------------------------------------------------------------------

    @Test
    fun `computes the small helpers the same way`() {
        val cases = Corpus.cases("helpers.json")
        assertCorpusSize(cases.size, 500, "helpers")

        for (case in cases) {
            val id = case.str("id")!!
            val score = case.int("score")!!
            val expect = case.get("expect").asJsonObject

            assertSameNullable(
                expect.bool("can_finish"),
                Darts.canFinish(score),
                "canFinish differs for '$id'",
            )
            assertSameNullable(
                expect.bool("is_bogey"),
                Darts.isBogey(score),
                "isBogey differs for '$id'",
            )
            assertSameStringList(
                expect.strList("chain"),
                Darts.chain(score),
                "chain differs for '$id'",
            )
            assertSameStringList(
                expect.strList("double_options"),
                Darts.doubleOptions(score),
                "doubleOptions differs for '$id'",
            )
            assertSameNullable(
                expect.str("words"),
                Darts.numberToWords(score),
                "numberToWords differs for '$id'",
            )
        }
    }
}